SELECT list_price_usd
FROM product_catalog
WHERE sku = 'SKU-GRW' AND effective_to IS NULL;

SELECT COUNT(*) AS n
FROM invoices
WHERE status = 'paid' AND paid_at IS NULL;

SELECT MAX(CASE WHEN event_value REGEXP '^[0-9]+(\\.[0-9]+)?$'
                THEN CAST(event_value AS DECIMAL(18,4)) END) AS max_value
FROM usage_events;

SELECT COUNT(DISTINCT
  TRIM(REGEXP_REPLACE(LOWER(c.company_name), ',? *(inc\\.?|incorporated|llc|ltd\\.?)$', ''))
) AS n
FROM deals d
JOIN customers c ON c.customer_id = d.acct_id
WHERE d.status = 'won';

SELECT COUNT(DISTINCT
  TRIM(REGEXP_REPLACE(LOWER(c.company_name), ',? *(inc\\.?|incorporated|llc|ltd\\.?)$', ''))
) AS n
FROM subscriptions s
JOIN customers c ON c.customer_id = s.customer_id
WHERE s.status = 'active';

SELECT ROUND(SUM(amount / 1.08), 2) AS won_net_usd
FROM deals
WHERE status = 'won';

SELECT DISTINCT industry FROM customers
WHERE industry IS NOT NULL
ORDER BY industry;
